  final int NAVY=Color.rgb(7,20,34), PANEL=Color.rgb(16,36,55), CARD=Color.rgb(20,45,67), BLUE=Color.rgb(55,132,238), CYAN=Color.rgb(51,205,220), ORANGE=Color.rgb(245,164,47), GREEN=Color.rgb(67,190,113), YELLOW=Color.rgb(247,207,77), RED=Color.rgb(229,82,74), STEEL=Color.rgb(154,174,194);
  LinearLayout root,wizard; RigView rig; TextView status,result; Spinner loadCase,viewMode,qProfile; EditText L,D,F,M,stations,layers,actCount,actCapacity,pressure,sf,padW,padL,deflection,linkLength,strokeMargin; SeekBar loadLevel; TextView loadLevelText; Button calc,auto;
  String[] CASES={"+Z Bending","-Z Bending","+Y Bending","-Y Bending","Pitch +My","Pitch -My","Roll +Mx","Roll -Mx","Yaw +Mz","Yaw -Mz","Combined Z+Pitch"};
  String[] VIEWS={"Side View","Top View","Front View","Symbolic Tree","Mechanical Rig","BOM","Compare"};
  String[] Q={"Elliptic","Uniform","Triangular root-high","Triangular tip-high","Parabolic"};

  @Override public void onCreate(Bundle b){super.onCreate(b);
    ScrollView sv=new ScrollView(this); root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(10),dp(10),dp(10),dp(28));root.setBackgroundColor(NAVY);sv.addView(root);
    root.addView(tx("EFT WHIFFLETREE DIGITAL ENGINEER",25,true,Color.WHITE));root.addView(tx("v1.6 • Professional 2D load-path • Side/Top/Front • Mechanical/BOM/Compare",12,false,Color.rgb(180,205,225)));

    LinearLayout selectors=new LinearLayout(this);selectors.setOrientation(LinearLayout.HORIZONTAL);
    loadCase=spinner(CASES);viewMode=spinner(VIEWS);selectors.addView(loadCase,new LinearLayout.LayoutParams(0,dp(50),1));selectors.addView(viewMode,new LinearLayout.LayoutParams(0,dp(50),1));root.addView(selectors,lp());
    status=card("Hazır",Color.rgb(13,47,70));root.addView(status,lp());

    rig=new RigView();root.addView(rig,new LinearLayout.LayoutParams(-1,dp(610)));

    LinearLayout levelBox=new LinearLayout(this);levelBox.setOrientation(LinearLayout.VERTICAL);levelBox.setPadding(dp(10),dp(6),dp(10),dp(6));levelBox.setBackground(bg(PANEL,10));
    loadLevelText=tx("Load level: 100%",13,true,Color.WHITE);levelBox.addView(loadLevelText);loadLevel=new SeekBar(this);loadLevel.setMax(100);loadLevel.setProgress(100);levelBox.addView(loadLevel,new LinearLayout.LayoutParams(-1,dp(42)));root.addView(levelBox,lp());

    wizard=new LinearLayout(this);wizard.setOrientation(LinearLayout.VERTICAL);wizard.setPadding(dp(10),dp(10),dp(10),dp(10));wizard.setBackground(bg(PANEL,12));root.addView(wizard,lp());
    wizard.addView(tx("DESIGN INPUTS — tüm alanlar varsayılanla çalışır",17,true,Color.WHITE));
    F=field("Target total load [kN]","305.7");M=field("Target moment [kN·m]","1280");L=field("Tank length [m]","7.6");D=field("Tank diameter [m]","0.64");stations=field("Station count (4-16)","12");
    wizard.addView(tx("q(x) profile",12,true,Color.rgb(185,210,230)));qProfile=spinner(Q);wizard.addView(qProfile,lp());
    layers=field("Whiffletree layer count (1-3)","3");actCount=field("Actuator count (1-8)","4");actCapacity=field("Actuator nominal capacity [kN]","120");pressure=field("Hydraulic pressure [bar]","210");sf=field("Sizing factor","1.50");padW=field("Load pad width [mm]","150");padL=field("Load pad length [mm]","250");deflection=field("Expected max EFT deflection [mm]","60");linkLength=field("Nominal link/rod length [mm]","600");strokeMargin=field("Stroke margin [%]","25");
    auto=new Button(this);auto.setText("AUTO DESIGN ACTUATOR COUNT");auto.setOnClickListener(v->{try{Calc c=compute(true);actCount.setText(String.valueOf(c.nAct));preview(c);result.setText("AUTO DESIGN: "+c.nAct+" actuator selected. 2D topology, mechanical rig and BOM updated.");}catch(Exception e){result.setText("Girişleri kontrol et.");}});wizard.addView(auto,lp());
    calc=new Button(this);calc.setText("HESAPLA + TÜM 2D GÖRÜNÜMLERİ GÜNCELLE");calc.setOnClickListener(v->calculate());wizard.addView(calc,lp());

    result=card("Side/Top/Front görünüşleri load case'e göre, ağaç ve actuator yerleşimi layer/actuator sayısına göre canlı güncellenir.",Color.rgb(12,34,52));result.setTextSize(13);root.addView(result,lp());
    root.addView(card("Mühendislik notu: v1.6 ön tasarım ve eğitim aracıdır. Nihai rig release için onaylı loads report, FEM, gerçek actuator/load-cell katalog rating'leri, fixture analizi ve kurum test prosedürü gerekir.",Color.rgb(66,46,12)),lp());

    TextWatcher tw=new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){safe();}public void afterTextChanged(Editable e){}};
    for(EditText e:new EditText[]{F,M,L,D,stations,layers,actCount,actCapacity,pressure,sf,padW,padL,deflection,linkLength,strokeMargin})e.addTextChangedListener(tw);
    android.widget.AdapterView.OnItemSelectedListener lis=new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?>p,View v,int pos,long id){safe();}public void onNothingSelected(android.widget.AdapterView<?>p){}};loadCase.setOnItemSelectedListener(lis);viewMode.setOnItemSelectedListener(lis);qProfile.setOnItemSelectedListener(lis);
    loadLevel.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean u){loadLevelText.setText("Load level: "+p+"%");safe();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
    setContentView(sv);safe();
  }

  Spinner spinner(String[] a){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));return s;}
  EditText field(String label,String def){wizard.addView(tx(label,12,true,Color.rgb(185,210,230)));EditText e=new EditText(this);e.setText(def);e.setTextColor(Color.WHITE);e.setTextSize(16);e.setSingleLine(true);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);e.setBackground(bg(Color.rgb(25,52,75),8));e.setPadding(dp(10),0,dp(10),0);wizard.addView(e,new LinearLayout.LayoutParams(-1,dp(44)));return e;}
  void safe(){try{preview(compute(false));}catch(Exception ignored){}}
  void preview(Calc c){rig.set(c,loadCase.getSelectedItemPosition(),viewMode.getSelectedItemPosition(),loadLevel.getProgress()/100.0);status.setText(String.format(Locale.US,"%s • %s • S=%d • L=%d • A=%d • ΣF %.1f kN • M %.1f kN·m",CASES[loadCase.getSelectedItemPosition()],VIEWS[viewMode.getSelectedItemPosition()],c.n,c.layers,c.nAct,c.sumF,c.calcM));}
  void calculate(){try{Calc c=compute(false);preview(c);StringBuilder s=new StringBuilder();s.append("EFT 2D DIGITAL ENGINEERING SUMMARY\n\n");s.append(String.format(Locale.US,"Case: %s\nq(x): %s\nTank L/D: %.2f / %.2f m\nStations: %d | Layers: %d | Actuators: %d\nΣF target/calc: %.1f / %.1f kN\nM target/calc: %.1f / %.1f kN·m\nMoment error: %.2f %%\n\n",CASES[loadCase.getSelectedItemPosition()],Q[qProfile.getSelectedItemPosition()],c.L,c.D,c.n,c.layers,c.nAct,c.targetF,c.sumF,c.targetM,c.calcM,c.mErr));
    s.append(String.format(Locale.US,"ACTUATOR PRE-DESIGN\nDesign load: %.1f kN\nNominal demand/actuator: %.1f kN\nEquivalent piston bore: %.1f mm @ %.0f bar\nLoad-cell class: ≥ %.0f kN\nRequired stroke envelope (simple geometry): %.1f mm\nLink angle @ max deflection: %.1f°\nGeometric transverse component: %.1f kN\n\n",c.designF,c.actLoad,c.bore,c.pbar,c.lc,c.strokeReq,c.linkAngle,c.sideLoad));
    s.append("STATION LOADS\n");for(int i=0;i<c.n;i++)s.append(String.format(Locale.US,"S%-2d x=%5.2f m   F=%6.1f kN\n",i+1,c.x[i],c.fi[i]));
    s.append("\nTREE\n").append(c.tree).append("\nBOM\n").append(c.bom).append("\n\nDESIGN GATES\n").append(c.gates);result.setText(s.toString());}catch(Exception e){result.setText("Geçersiz giriş. Sayısal alanları kontrol et.");}}

  Calc compute(boolean opt){Calc c=new Calc();c.L=Math.max(.5,d(L));c.D=Math.max(.1,d(D));c.targetF=Math.abs(d(F));c.targetM=d(M);c.n=clamp((int)Math.round(d(stations)),4,16);c.layers=clamp((int)Math.round(d(layers)),1,3);double cap=Math.max(1,d(actCapacity));c.pbar=Math.max(1,d(pressure));c.sf=Math.max(1,d(sf));c.designF=c.targetF*c.sf;int manual=clamp((int)Math.round(d(actCount)),1,8);int minCap=(int)Math.ceil(c.designF/cap);int minTopo=Math.max(1,(int)Math.ceil(c.n/Math.pow(2,c.layers)));c.nAct=opt?clamp(Math.max(minCap,minTopo),1,8):manual;c.actLoad=c.designF/c.nAct;c.bore=Math.sqrt(4*(c.actLoad*1000)/(c.pbar*100000)/Math.PI)*1000;c.lc=std(c.actLoad*1.2);
    c.x=new double[c.n];c.fi=new double[c.n];double[] w=new double[c.n];double sw=0;int q=qProfile.getSelectedItemPosition();for(int i=0;i<c.n;i++){double u=(i+.5)/c.n;c.x[i]=u*c.L;if(q==0)w[i]=Math.sqrt(Math.max(0,1-Math.pow(2*u-1,2)))+.05;else if(q==1)w[i]=1;else if(q==2)w[i]=1.15-u;else if(q==3)w[i]=.15+u;else w[i]=.25+4*u*(1-u);sw+=w[i];}for(int i=0;i<c.n;i++)c.fi[i]=c.targetF*w[i]/sw;
    double desired=Math.abs(c.targetM),base=0;for(int i=0;i<c.n;i++)base+=c.fi[i]*c.x[i];double mean=0;for(double xx:c.x)mean+=xx;mean/=c.n;double den=0;for(double xx:c.x)den+=(xx-mean)*(xx-mean);double delta=desired-base;if(Math.abs(delta)>1e-9&&den>1e-9)for(int i=0;i<c.n;i++)c.fi[i]+=delta*(c.x[i]-mean)/den;boolean neg=false;for(double v:c.fi)if(v<0)neg=true;if(neg){for(int i=0;i<c.n;i++)c.fi[i]=Math.max(.001,c.fi[i]);double ss=0;for(double v:c.fi)ss+=v;for(int i=0;i<c.n;i++)c.fi[i]*=c.targetF/ss;}
    c.sumF=0;c.calcM=0;for(int i=0;i<c.n;i++){c.sumF+=c.fi[i];c.calcM+=c.fi[i]*c.x[i];}if(c.targetM<0)c.calcM=-c.calcM;c.mErr=Math.abs(c.targetM)>1e-6?100*(c.calcM-c.targetM)/Math.abs(c.targetM):0;
    int branch=c.n,beams=0;for(int l=0;l<c.layers&&branch>1;l++){beams+=branch/2;branch=(branch+1)/2;}c.beams=beams;c.topBranches=branch;c.tree=synth(c);c.bom=bom(c);
    double def=Math.max(0,d(deflection)), link=Math.max(50,d(linkLength)), margin=Math.max(0,d(strokeMargin));c.strokeReq=def*(1+margin/100.0)+20;c.linkAngle=Math.toDegrees(Math.atan2(def,link));c.sideLoad=c.actLoad*Math.sin(Math.toRadians(c.linkAngle));c.padArea=Math.max(1,d(padW)*d(padL));double maxFi=0;for(double f:c.fi)maxFi=Math.max(maxFi,f);c.padPressure=maxFi*1000/(c.padArea/1e6)/1e6;c.gates=gates(c,cap);return c;}

  String synth(Calc c){StringBuilder sb=new StringBuilder();ArrayList<Double> vals=new ArrayList<>();for(double f:c.fi)vals.add(f*c.sf);for(int lev=1;lev<=c.layers&&vals.size()>1;lev++){ArrayList<Double> nx=new ArrayList<>();sb.append("Layer ").append(lev).append(":\n");for(int i=0;i<vals.size();i+=2){if(i+1<vals.size()){double a=vals.get(i),b=vals.get(i+1),sum=a+b;sb.append(String.format(Locale.US," B%d  %.1f + %.1f = %.1f kN | pivot %.0f/%.0f %%\n",i/2+1,a,b,sum,100*b/sum,100*a/sum));nx.add(sum);}else{nx.add(vals.get(i));sb.append(String.format(Locale.US," B%d  single %.1f kN\n",i/2+1,vals.get(i)));}}vals=nx;}sb.append("Top branches after selected layers: ").append(vals.size()).append("\n");return sb.toString();}
  String bom(Calc c){int piv=c.beams*3;int links=c.n+Math.max(0,c.beams-c.topBranches);int clevis=c.n+c.nAct;int anchors=Math.max(4,c.nAct*2);return "Actuator: "+c.nAct+" ea, demand "+fmt(c.actLoad)+" kN\nLoad cell: "+c.nAct+" ea, ≥"+fmt(c.lc)+" kN\nServo valve/control channel: "+c.nAct+" ea\nActuator spherical bearing: "+c.nAct+" ea\nStation rod-end: "+c.n+" ea\nWhiffletree beam: "+c.beams+" ea\nPivot/pin/washer set: "+piv+" sets\nTie rod/link: "+links+" ea\nClevis: "+clevis+" ea\nLoad pad/saddle: "+c.n+" ea\nHydraulic hose pair: "+c.nAct+" sets\nPosition/LVDT channel: "+c.nAct+" ch\nForce DAQ channel: "+c.nAct+" ch\nStrongback: 1 assembly\nFloor anchor: "+anchors+" ea\nHP manifold: 1 set\nEmergency pressure dump: 1 set";}
  String gates(Calc c,double cap){StringBuilder s=new StringBuilder();s.append(Math.abs(c.mErr)<=1?"PASS  Force/moment equivalence\n":"WARN  Moment error >1%\n");s.append(c.actLoad<=cap?"PASS  Actuator nominal capacity\n":"FAIL  Actuator nominal capacity\n");s.append(c.linkAngle<=6?"PASS  Preliminary link angle ≤6°\n":"WARN  Link angle >6°; joint/side-load review\n");s.append(c.padPressure<=8?"PASS  Mean pad pressure preliminary screen\n":"WARN  Pad mean pressure >8 MPa; local FEM required\n");s.append("REVIEW beam stress/deflection, pin/clevis/lug allowables, strongback/floor reactions and fatigue separately.");return s.toString();}

  class RigView extends View{
    Paint p=new Paint(Paint.ANTI_ALIAS_FLAG),t=new Paint(Paint.ANTI_ALIAS_FLAG);Calc c;int ci=0,mode=0;double level=1;RigView(){super(MainActivity.this);setBackgroundColor(Color.rgb(4,15,27));t.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));}
    void set(Calc x,int caseIdx,int m,double lv){c=x;ci=caseIdx;mode=m;level=lv;invalidate();}
    protected void onDraw(Canvas cn){super.onDraw(cn);if(c==null)return;drawHeader(cn);if(mode==0)drawSide(cn);else if(mode==1)drawTop(cn);else if(mode==2)drawFront(cn);else if(mode==3)drawTree(cn,false);else if(mode==4)drawMechanical(cn);else if(mode==5)drawBom(cn);else drawCompare(cn);}
    void drawHeader(Canvas cn){t.setColor(Color.WHITE);t.setTextSize(dp(12));cn.drawText(CASES[ci]+"  •  "+VIEWS[mode],dp(10),dp(20),t);t.setTextSize(dp(9));t.setColor(Color.rgb(180,205,225));cn.drawText(String.format(Locale.US,"Load %.0f%% | ΣF %.1f kN | M %.1f kN·m | %dL/%dA",level*100,c.sumF*level,c.calcM*level,c.layers,c.nAct),dp(10),dp(38),t);}
    void drawTankSide(Canvas cn,float left,float right,float y){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(55,69,84));RectF r=new RectF(left,y-dp(28),right,y+dp(28));cn.drawRoundRect(r,dp(28),dp(28),p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(STEEL);cn.drawRoundRect(r,dp(28),dp(28),p);p.setColor(Color.rgb(95,115,135));cn.drawLine(left+dp(32),y-dp(28),left+dp(32),y+dp(28),p);cn.drawLine(right-dp(38),y-dp(28),right-dp(38),y+dp(28),p);}
    void drawSide(Canvas cn){int w=getWidth(),h=getHeight();float left=w*.06f,right=w*.95f,y=h*.34f;drawTankSide(cn,left,right,y);float[] sx=stationXs(left,right);for(int i=0;i<c.n;i++){p.setColor(CYAN);p.setStrokeWidth(2);cn.drawLine(sx[i],y-dp(28),sx[i],y+dp(28),p);drawPad(cn,sx[i],y+dp(31));drawCaseVector(cn,sx[i],y-dp(31),i,c.fi[i]*level,false);labelStation(cn,sx[i],y+dp(55),i,c.fi[i]*level);}drawCompactTree(cn,sx,y+dp(75),h-dp(45));}
    void drawTop(Canvas cn){int w=getWidth(),h=getHeight();float left=w*.06f,right=w*.95f,y=h*.34f;drawTankSide(cn,left,right,y);float[] sx=stationXs(left,right);for(int i=0;i<c.n;i++){p.setColor(CYAN);p.setStrokeWidth(2);cn.drawLine(sx[i],y-dp(28),sx[i],y+dp(28),p);boolean lateral=(ci==2||ci==3||ci==8||ci==9||ci==10);if(lateral)drawHorizontalVector(cn,sx[i],y,i,c.fi[i]*level);else drawCaseVector(cn,sx[i],y-dp(31),i,c.fi[i]*level,false);labelStation(cn,sx[i],y+dp(55),i,c.fi[i]*level);}drawActuatorPlan(cn,left,right,y+dp(110));}
    void drawFront(Canvas cn){int w=getWidth(),h=getHeight();float cx=w*.5f,cy=h*.35f,rad=Math.min(w,h)*.18f;p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(55,69,84));cn.drawCircle(cx,cy,rad,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);p.setColor(STEEL);cn.drawCircle(cx,cy,rad,p);t.setColor(Color.WHITE);t.setTextSize(dp(9));cn.drawText("EFT cross-section",cx-dp(35),cy+dp(4),t);int count=Math.min(c.n,8);for(int i=0;i<count;i++){double a=2*Math.PI*i/count-Math.PI/2;float x=cx+(float)Math.cos(a)*rad,y=cy+(float)Math.sin(a)*rad;drawPad(cn,x,y);if(ci==6||ci==7||ci==10){float s=(ci==7?-1:1);drawVector(cn,x,y,x+(float)Math.cos(a)*dp(45)*s,y+(float)Math.sin(a)*dp(45)*s,ORANGE);}else if(ci==2||ci==3||ci==8||ci==9)drawVector(cn,x,y,x+(ci==3||ci==9?-dp(50):dp(50)),y,BLUE);else drawVector(cn,x,y,x,y-(ci==1?-1:1)*dp(50),BLUE);}drawActuatorPlan(cn,w*.08f,w*.92f,h*.7f);}
    void drawTree(Canvas cn,boolean mechanics){int w=getWidth(),h=getHeight();float left=w*.05f,right=w*.95f;float[] sx=stationXs(left,right);float sy=dp(85);t.setTextSize(dp(8));t.setColor(Color.WHITE);for(int i=0;i<c.n;i++){cn.drawText("S"+(i+1),sx[i]-dp(6),sy,t);drawPad(cn,sx[i],sy+dp(14));}ArrayList<Node> nodes=new ArrayList<>();for(int i=0;i<c.n;i++)nodes.add(new Node(sx[i],sy+dp(25),(float)(c.fi[i]*c.sf)));float gap=Math.min(dp(95),(h-dp(180))/(float)Math.max(1,c.layers+1));for(int lev=1;lev<=c.layers&&nodes.size()>1;lev++){float yy=sy+dp(25)+gap*lev;nodes=drawLevel(cn,nodes,yy,lev,mechanics);}drawActuatorsToNodes(cn,nodes,Math.min(h-dp(55),sy+dp(25)+gap*(c.layers+1)),mechanics);}
    ArrayList<Node> drawLevel(Canvas cn,ArrayList<Node> nodes,float y,int lev,boolean mech){ArrayList<Node> nx=new ArrayList<>();int col=lev==1?ORANGE:(lev==2?YELLOW:CYAN);for(int i=0;i<nodes.size();i+=2){if(i+1<nodes.size()){Node a=nodes.get(i),b=nodes.get(i+1);float sum=a.f+b.f;float px=(a.x*b.f+b.x*a.f)/sum;p.setColor(col);p.setStrokeWidth(mech?dp(5):dp(3));cn.drawLine(a.x,y,b.x,y,p);p.setStrokeWidth(dp(2));cn.drawLine(a.x,a.y,a.x,y,p);cn.drawLine(b.x,b.y,b.x,y,p);p.setStyle(Paint.Style.FILL);cn.drawCircle(px,y,dp(4),p);p.setStyle(Paint.Style.STROKE);t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText(String.format(Locale.US,"L%d %.0f kN",lev,sum),px-dp(20),y-dp(7),t);nx.add(new Node(px,y,sum));}else nx.add(nodes.get(i));}return nx;}
    void drawMechanical(Canvas cn){int w=getWidth(),h=getHeight();float left=w*.05f,right=w*.95f,tankY=dp(120);drawTankSide(cn,left,right,tankY);float[] sx=stationXs(left,right);for(int i=0;i<c.n;i++){drawPad(cn,sx[i],tankY+dp(31));p.setColor(STEEL);p.setStrokeWidth(2);cn.drawLine(sx[i],tankY+dp(35),sx[i],tankY+dp(62),p);}ArrayList<Node> nodes=new ArrayList<>();for(int i=0;i<c.n;i++)nodes.add(new Node(sx[i],tankY+dp(62),(float)(c.fi[i]*c.sf)));float gap=dp(70);for(int lev=1;lev<=c.layers&&nodes.size()>1;lev++)nodes=drawLevel(cn,nodes,tankY+dp(62)+gap*lev,lev,true);float ay=Math.min(h-dp(90),tankY+dp(62)+gap*(c.layers+1));drawActuatorsToNodes(cn,nodes,ay,true);p.setColor(Color.rgb(84,98,112));p.setStrokeWidth(dp(8));cn.drawLine(left,ay+dp(58),right,ay+dp(58),p);t.setColor(Color.rgb(190,210,225));t.setTextSize(dp(8));cn.drawText("STRONGBACK / STRONG FLOOR REACTION",left,ay+dp(75),t);}
    void drawActuatorsToNodes(Canvas cn,ArrayList<Node> nodes,float ay,boolean mech){int w=getWidth();for(int a=0;a<c.nAct;a++){float ax=w*(.08f+.84f*(a+.5f)/c.nAct);Node target=nodes.get(Math.min(nodes.size()-1,(int)Math.floor((a+.5)*nodes.size()/c.nAct)));p.setColor(Color.WHITE);p.setStrokeWidth(2);cn.drawLine(ax,ay-dp(45),target.x,target.y,p);if(mech){drawCylinder(cn,ax,ay);drawLoadCell(cn,ax,ay-dp(52));drawJoint(cn,ax,ay-dp(69));}else{p.setStyle(Paint.Style.FILL);p.setColor(GREEN);cn.drawRoundRect(new RectF(ax-dp(14),ay-dp(35),ax+dp(14),ay+dp(5)),dp(5),dp(5),p);p.setStyle(Paint.Style.STROKE);}t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText("A"+(a+1),ax-dp(6),ay+dp(20),t);cn.drawText(String.format(Locale.US,"%.0f",c.actLoad),ax-dp(8),ay+dp(32),t);}}
    void drawCylinder(Canvas cn,float x,float y){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(62,84,104));cn.drawRoundRect(new RectF(x-dp(15),y-dp(35),x+dp(15),y+dp(7)),dp(5),dp(5),p);p.setColor(GREEN);cn.drawRect(x-dp(3),y-dp(54),x+dp(3),y-dp(35),p);p.setStyle(Paint.Style.STROKE);p.setColor(STEEL);p.setStrokeWidth(2);cn.drawRoundRect(new RectF(x-dp(15),y-dp(35),x+dp(15),y+dp(7)),dp(5),dp(5),p);}
    void drawLoadCell(Canvas cn,float x,float y){p.setStyle(Paint.Style.FILL);p.setColor(YELLOW);cn.drawRoundRect(new RectF(x-dp(9),y-dp(6),x+dp(9),y+dp(6)),dp(3),dp(3),p);p.setStyle(Paint.Style.STROKE);t.setColor(Color.WHITE);t.setTextSize(dp(6));cn.drawText("LC",x-dp(5),y+dp(2),t);}
    void drawJoint(Canvas cn,float x,float y){p.setStyle(Paint.Style.FILL);p.setColor(ORANGE);cn.drawCircle(x,y,dp(5),p);p.setStyle(Paint.Style.STROKE);}
    void drawBom(Canvas cn){int w=getWidth();String[] lines=c.bom.split("\\n");float y=dp(72);t.setTextSize(dp(9));for(String line:lines){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(17,40,59));cn.drawRoundRect(new RectF(dp(12),y-dp(14),w-dp(12),y+dp(16)),dp(6),dp(6),p);t.setColor(Color.WHITE);cn.drawText(line,dp(22),y+dp(4),t);y+=dp(37);if(y>getHeight()-dp(10))break;}}
    void drawCompare(Canvas cn){int w=getWidth();float y=dp(82);t.setTextSize(dp(9));for(int a=2;a<=5;a++){double demand=c.designF/a;double util=demand/Math.max(1,d(actCapacity))*100;int topo=Math.max(1,(int)Math.ceil(c.n/(double)a));p.setStyle(Paint.Style.FILL);p.setColor(util<=100?Color.rgb(20,70,55):Color.rgb(82,43,43));cn.drawRoundRect(new RectF(dp(12),y-dp(18),w-dp(12),y+dp(52)),dp(8),dp(8),p);t.setColor(Color.WHITE);cn.drawText(a+" actuators",dp(24),y,t);cn.drawText(String.format(Locale.US,"%.1f kN/act | capacity util %.0f%%",demand,util),dp(24),y+dp(17),t);cn.drawText("Approx station groups/act: "+topo+" | layer selected: "+c.layers,dp(24),y+dp(34),t);y+=dp(82);}t.setColor(Color.rgb(190,210,225));cn.drawText("Green = nominal capacity screen passes; final choice also requires stroke, geometry and control review.",dp(12),y+dp(10),t);}
    void drawCompactTree(Canvas cn,float[] sx,float top,float bottom){ArrayList<Node> nodes=new ArrayList<>();for(int i=0;i<c.n;i++)nodes.add(new Node(sx[i],top,(float)(c.fi[i]*c.sf)));float available=Math.max(dp(120),bottom-top);float gap=Math.min(dp(55),available/(c.layers+1));for(int lev=1;lev<=c.layers&&nodes.size()>1;lev++)nodes=drawLevel(cn,nodes,top+gap*lev,lev,false);drawActuatorsToNodes(cn,nodes,Math.min(bottom,top+gap*(c.layers+1)),false);}
    void drawActuatorPlan(Canvas cn,float left,float right,float y){for(int a=0;a<c.nAct;a++){float x=left+(right-left)*(a+.5f)/c.nAct;drawCylinder(cn,x,y);t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText("A"+(a+1),x-dp(6),y+dp(24),t);}p.setColor(Color.rgb(80,96,112));p.setStrokeWidth(dp(7));cn.drawLine(left,y+dp(35),right,y+dp(35),p);}
    float[] stationXs(float left,float right){float[] a=new float[c.n];for(int i=0;i<c.n;i++)a[i]=left+(float)(c.x[i]/c.L)*(right-left);return a;}
    void drawCaseVector(Canvas cn,float x,float y,int i,double f,boolean front){float len=dp(25)+(float)Math.min(dp(55),Math.abs(f)*.55);boolean down=(ci==1);if(ci==4||ci==5)down=(i>=c.n/2)^(ci==5);if(ci==6||ci==7)down=(i%2==0)^(ci==7);if(ci==2||ci==3||ci==8||ci==9){drawHorizontalVector(cn,x,y,i,f);return;}drawVector(cn,x,y,x,y+(down?len:-len),ci==10?ORANGE:BLUE);}
    void drawHorizontalVector(Canvas cn,float x,float y,int i,double f){float len=dp(28)+(float)Math.min(dp(48),Math.abs(f)*.45);boolean leftward=(ci==3||ci==9);if(ci==8||ci==9)leftward=(i>=c.n/2)^(ci==9);drawVector(cn,x,y,x+(leftward?-len:len),y,BLUE);}
    void drawVector(Canvas cn,float x1,float y1,float x2,float y2,int col){p.setColor(col);p.setStrokeWidth(dp(3));cn.drawLine(x1,y1,x2,y2,p);double ang=Math.atan2(y2-y1,x2-x1);float ah=dp(7);float a1=(float)(ang+2.5),a2=(float)(ang-2.5);cn.drawLine(x2,y2,x2+(float)Math.cos(a1)*ah,y2+(float)Math.sin(a1)*ah,p);cn.drawLine(x2,y2,x2+(float)Math.cos(a2)*ah,y2+(float)Math.sin(a2)*ah,p);}
    void drawPad(Canvas cn,float x,float y){p.setStyle(Paint.Style.FILL);p.setColor(ORANGE);cn.drawRoundRect(new RectF(x-dp(7),y-dp(4),x+dp(7),y+dp(4)),dp(2),dp(2),p);p.setStyle(Paint.Style.STROKE);}
    void labelStation(Canvas cn,float x,float y,int i,double f){t.setColor(Color.WHITE);t.setTextSize(dp(7));cn.drawText("S"+(i+1),x-dp(6),y,t);cn.drawText(String.format(Locale.US,"%.0f",f),x-dp(7),y+dp(10),t);}
  }
